import tailwindcss from '@tailwindcss/vite'
import react from '@vitejs/plugin-react'
import { defineConfig } from 'vitest/config'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    proxy: {
      '/api': 'http://localhost:8787',
    },
  },
  test: {
    environment: 'node',
    include: ['src/**/*.test.ts', 'api/**/*.test.ts'],
  },
})

import { useEffect, useMemo, useRef, useState } from 'react'
import { ComparisonTable } from './components/ComparisonTable'
import { CompatibilityExplainer } from './components/CompatibilityExplainer'
import { DatasheetImportForm } from './components/DatasheetImportForm'
import { FovCone3D } from './components/FovCone3D'
import { FovReadout } from './components/FovReadout'
import { LensForm } from './components/LensForm'
import { SensorCompare2D } from './components/SensorCompare2D'
import { SensorForm } from './components/SensorForm'
import { WizardPanel } from './components/WizardPanel'
import { useAppData } from './store/useAppData'
import {
  addCameraSlot,
  computeTwoCameraView,
  createSlot,
  effectiveWorkingDistance,
  getSliderBounds,
  loadCameraSlots,
  panelLayout,
  removeCameraSlot,
  saveCameraSlots,
  updateCameraSlot,
} from './lib/twoCamera'
import type { CameraSlot } from './lib/twoCamera'
import type { Lens, Sensor } from './lib/types'

type AddMode = 'none' | 'manual' | 'import'

function Section({ title, subtitle, children }: { title: string; subtitle?: string; children: React.ReactNode }) {
  return (
    <section className="flex flex-col gap-3 rounded-xl border border-neutral-200 bg-white p-4 shadow-sm sm:p-5">
      <div>
        <h2 className="text-base font-semibold text-neutral-800">{title}</h2>
        {subtitle && <p className="text-sm text-neutral-500">{subtitle}</p>}
      </div>
      {children}
    </section>
  )
}

export default function App() {
  const { sensors, lenses, addSensor, removeSensor, addLens, removeLens, exportJson, importJson } = useAppData()

  const [sensorAddMode, setSensorAddMode] = useState<AddMode>('none')
  const [lensAddMode, setLensAddMode] = useState<AddMode>('none')

  // The camera comparison slots. Restored from localStorage when present so a
  // 2-panel comparison survives reload; otherwise start with a single camera.
  const [cameras, setCameras] = useState<CameraSlot[]>(() => loadCameraSlots() ?? [createSlot(null, null)])

  useEffect(() => {
    saveCameraSlots(cameras)
  }, [cameras])

  const fileInputRef = useRef<HTMLInputElement>(null)
  const [importError, setImportError] = useState<string | null>(null)

  function updateCamera(id: string, patch: Partial<CameraSlot>) {
    // Lenses passed so a lens swap re-clamps WD into the new lens's valid
    // range (fixes slider-shows-valid / state-stays-invalid desync).
    setCameras((prev) => updateCameraSlot(prev, id, patch, lenses))
  }

  function addCamera() {
    // Seeded from the last slot so it's an easy "tweak one thing" comparison.
    setCameras((prev) => addCameraSlot(prev))
  }

  function removeCamera(id: string) {
    setCameras((prev) => removeCameraSlot(prev, id))
  }

  // Resolve each slot + shared 1:1 scale + de-duplicated in-play sets via the
  // tested lib helpers (single source of truth with src/lib/twoCamera.test.ts).
  const view = useMemo(() => computeTwoCameraView(sensors, lenses, cameras), [sensors, lenses, cameras])
  const resolved = view.resolved
  // Shared world scale across every panel → identical camera position and true 1:1 framing.
  const sharedScaleMm = view.sharedScale
  // Sensors currently in play, de-duplicated, feed the to-scale size comparison automatically.
  const camerasSensors = view.playSensors as Sensor[]
  const camerasLenses = view.playLenses as Lens[]

  const firstSensor = resolved[0]?.sensor ?? null

  function handleExportClick() {
    const blob = new Blob([exportJson()], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'camera-selection-tool-export.json'
    a.click()
    URL.revokeObjectURL(url)
  }

  async function handleImportFile(file: File) {
    setImportError(null)
    try {
      importJson(await file.text())
    } catch (err) {
      setImportError(err instanceof Error ? err.message : 'Could not import that file.')
    }
  }

  const { gridColsClass, panelHeight } = panelLayout(cameras.length)
  const maxedOut = cameras.length >= 4

  return (
    <div className="min-h-screen bg-neutral-100">
      <header className="sticky top-0 z-20 border-b border-neutral-200 bg-white/85 backdrop-blur">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-3 px-4 py-3 sm:px-6">
          <div className="flex items-center gap-3">
            <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-slate-900 text-sm font-bold text-white">CL</span>
            <div>
              <h1 className="text-lg font-bold leading-tight text-neutral-900">Camera &amp; Lens Selection Tool</h1>
              <p className="text-xs text-neutral-500">Compare machine-vision cameras side by side at a true 1:1 field-of-view scale.</p>
            </div>
          </div>
          <div className="flex gap-2">
            <button onClick={handleExportClick} className="rounded border border-neutral-300 bg-white px-3 py-1.5 text-sm hover:bg-neutral-50">
              Export JSON
            </button>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="rounded border border-neutral-300 bg-white px-3 py-1.5 text-sm hover:bg-neutral-50"
            >
              Import JSON
            </button>
            <input
              ref={fileInputRef}
              type="file"
              accept="application/json"
              className="hidden"
              onChange={(e) => e.target.files?.[0] && handleImportFile(e.target.files[0])}
            />
          </div>
        </div>
      </header>

      <div className="mx-auto grid max-w-7xl grid-cols-1 gap-6 p-4 sm:p-6 lg:grid-cols-[320px_1fr] lg:items-start">
        {importError && <p className="text-sm text-red-700 lg:col-span-2">{importError}</p>}

        {/* Left sidebar: the sensor/lens library. Anything added here (manually or from a datasheet)
            becomes selectable in every camera's dropdowns. */}
        <aside className="flex flex-col gap-4 lg:sticky lg:top-20">
          <Section title="Sensors" subtitle="Add sensors manually or from a datasheet link — then pick them per camera.">
            <ul className="divide-y divide-neutral-200">
              {sensors.map((sensor) => (
                <li key={sensor.id} className="flex flex-wrap items-center gap-2 py-2">
                  <span className="text-sm font-medium text-neutral-800">{sensor.name}</span>
                  <span className="text-xs text-neutral-500">
                    {sensor.widthMm.toFixed(2)}x{sensor.heightMm.toFixed(2)}mm, {sensor.mount}-mount
                  </span>
                  <button onClick={() => removeSensor(sensor.id)} className="ml-auto text-xs text-red-600 hover:underline">
                    Remove
                  </button>
                </li>
              ))}
              {sensors.length === 0 && <li className="py-2 text-sm text-neutral-400">No sensors yet.</li>}
            </ul>

            {sensorAddMode === 'none' && (
              <div className="flex flex-wrap gap-2">
                <button onClick={() => setSensorAddMode('import')} className="rounded bg-blue-600 px-3 py-1.5 text-sm text-white hover:bg-blue-700">
                  From datasheet link
                </button>
                <button onClick={() => setSensorAddMode('manual')} className="rounded border border-neutral-300 px-3 py-1.5 text-sm hover:bg-neutral-100">
                  Add manually
                </button>
              </div>
            )}
            {sensorAddMode === 'import' && (
              <DatasheetImportForm
                kind="sensor"
                onSaveSensor={(s) => {
                  addSensor(s)
                  setSensorAddMode('none')
                }}
                onCancel={() => setSensorAddMode('none')}
              />
            )}
            {sensorAddMode === 'manual' && (
              <SensorForm
                source="manual"
                onSave={(s) => {
                  addSensor(s)
                  setSensorAddMode('none')
                }}
                onCancel={() => setSensorAddMode('none')}
              />
            )}
          </Section>

          <Section title="Lenses" subtitle="Add lenses manually or from a datasheet link — then pick them per camera.">
            <ul className="divide-y divide-neutral-200">
              {lenses.map((lens) => (
                <li key={lens.id} className="flex flex-wrap items-center gap-2 py-2">
                  <span className="text-sm font-medium text-neutral-800">{lens.name}</span>
                  <span className="text-xs text-neutral-500">
                    {lens.focalLengthMm}mm, {lens.mount}-mount, {lens.imageCircleMm}mm circle
                  </span>
                  <button onClick={() => removeLens(lens.id)} className="ml-auto text-xs text-red-600 hover:underline">
                    Remove
                  </button>
                </li>
              ))}
              {lenses.length === 0 && <li className="py-2 text-sm text-neutral-400">No lenses yet.</li>}
            </ul>

            {lensAddMode === 'none' && (
              <div className="flex flex-wrap gap-2">
                <button onClick={() => setLensAddMode('import')} className="rounded bg-blue-600 px-3 py-1.5 text-sm text-white hover:bg-blue-700">
                  From datasheet link
                </button>
                <button onClick={() => setLensAddMode('manual')} className="rounded border border-neutral-300 px-3 py-1.5 text-sm hover:bg-neutral-100">
                  Add manually
                </button>
              </div>
            )}
            {lensAddMode === 'import' && (
              <DatasheetImportForm
                kind="lens"
                onSaveLens={(l) => {
                  addLens(l)
                  setLensAddMode('none')
                }}
                onCancel={() => setLensAddMode('none')}
              />
            )}
            {lensAddMode === 'manual' && (
              <LensForm
                source="manual"
                onSave={(l) => {
                  addLens(l)
                  setLensAddMode('none')
                }}
                onCancel={() => setLensAddMode('none')}
              />
            )}
          </Section>
        </aside>

        {/* Main column: the side-by-side camera comparison, plus the 2D size chart and lens table. */}
        <main className="flex min-w-0 flex-col gap-6">
          <Section
            title="Application wizard"
            subtitle="Describe the imaging task — target field of view (or smallest feature), working distance, interface and shutter needs — and get the required focal range plus a ranked shortlist."
          >
            <WizardPanel sensors={sensors} lenses={lenses} />
          </Section>

          <div className="flex flex-wrap items-center justify-between gap-2">
            <div>
              <h2 className="text-base font-semibold text-neutral-800">Camera comparison</h2>
              <p className="text-sm text-neutral-500">
                Each panel is one camera at the same shared scale, so the 3D views are a genuine 1:1 comparison.
              </p>
            </div>
            <button
              onClick={addCamera}
              disabled={maxedOut}
              className="rounded bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-40"
            >
              + Add camera{maxedOut ? ' (max 4)' : ''}
            </button>
          </div>

          <div className={`grid gap-4 ${gridColsClass}`}>
            {resolved.map(({ cam, sensor, lens, effectiveWd }, index) => {
              const { min: sliderMin, max: sliderMax } = getSliderBounds(lens?.focalLengthMm ?? null)
              return (
                <section key={cam.id} className="flex flex-col gap-3 rounded-xl bg-slate-950 p-4 shadow-lg ring-1 ring-slate-900/10">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-semibold text-slate-100">Camera {index + 1}</p>
                    {cameras.length > 1 && (
                      <button onClick={() => removeCamera(cam.id)} className="text-xs text-slate-400 hover:text-red-300">
                        Remove
                      </button>
                    )}
                  </div>

                  <div className="grid grid-cols-2 gap-2">
                    <label className="flex flex-col gap-1 text-xs text-slate-300">
                      <span>Sensor</span>
                      <select
                        className="rounded-md border border-slate-700 bg-slate-800 p-1.5 text-sm text-slate-100"
                        value={sensor?.id ?? ''}
                        onChange={(e) => updateCamera(cam.id, { sensorId: e.target.value })}
                      >
                        {sensors.length === 0 && <option value="">No sensors yet</option>}
                        {sensors.map((s) => (
                          <option key={s.id} value={s.id}>
                            {s.name}
                          </option>
                        ))}
                      </select>
                    </label>
                    <label className="flex flex-col gap-1 text-xs text-slate-300">
                      <span>Lens</span>
                      <select
                        className="rounded-md border border-slate-700 bg-slate-800 p-1.5 text-sm text-slate-100"
                        value={lens?.id ?? ''}
                        onChange={(e) => updateCamera(cam.id, { lensId: e.target.value })}
                      >
                        {lenses.length === 0 && <option value="">No lenses yet</option>}
                        {lenses.map((l) => (
                          <option key={l.id} value={l.id}>
                            {l.name}
                          </option>
                        ))}
                      </select>
                    </label>
                  </div>

                  <label className="flex flex-col gap-1 text-xs text-slate-300">
                    <div className="flex items-center justify-between">
                      <span>Working distance</span>
                      <span className="font-mono text-slate-100 tabular-nums">{effectiveWd}mm</span>
                    </div>
                    <input
                      type="range"
                      min={sliderMin}
                      max={sliderMax}
                      value={effectiveWd}
                      onChange={(e) => updateCamera(cam.id, { workingDistanceMm: Number(e.target.value) })}
                      className="accent-sky-400"
                    />
                  </label>

                  {sensor && lens ? (
                    <>
                      <FovCone3D
                        sensor={sensor}
                        lens={lens}
                        workingDistanceMm={effectiveWd}
                        sceneScaleMm={sharedScaleMm}
                        heightClass={panelHeight}
                      />
                      <FovReadout sensor={sensor} lens={lens} workingDistanceMm={effectiveWorkingDistance(cam, lens)} />
                    </>
                  ) : (
                    <div className={`flex ${panelHeight} items-center justify-center rounded-xl bg-slate-900 text-sm text-slate-400`}>
                      Add a sensor and a lens on the left to view this camera.
                    </div>
                  )}
                </section>
              )
            })}
          </div>

          <Section title="Sensor size comparison" subtitle="Drawn to scale from the sensors used across the cameras above.">
            <SensorCompare2D sensors={camerasSensors} />
          </Section>

          <Section
            title="Comparison: first camera's sensor vs. the lenses in play"
            subtitle="Uses Camera 1's sensor and every lens currently selected across the cameras."
          >
            {!firstSensor ? (
              <p className="text-sm text-neutral-500">Add a sensor to enable this comparison.</p>
            ) : (
              <ComparisonTable sensor={firstSensor} lenses={camerasLenses} workingDistanceMm={resolved[0]?.effectiveWd ?? 300} />
            )}
            {firstSensor && camerasLenses[0] && (
              <div className="mt-2 flex flex-col gap-2">
                <h3 className="text-sm font-semibold text-neutral-800">
                  Why this fits (or doesn't): {firstSensor.name} + {camerasLenses[0].name}
                </h3>
                <CompatibilityExplainer sensor={firstSensor} lens={camerasLenses[0]} />
              </div>
            )}
          </Section>
        </main>
      </div>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import type { Lens, Sensor } from '../lib/types'
import { exportDataAsJson, importDataFromJson, loadData, saveData, type StoredData } from './persistence'

function makeId(prefix: string): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
}

export function useAppData() {
  const [data, setData] = useState<StoredData>(() => loadData())

  useEffect(() => {
    saveData(data)
  }, [data])

  const addSensor = useCallback((sensor: Omit<Sensor, 'id'>) => {
    const withId: Sensor = { ...sensor, id: makeId('sensor') }
    setData((prev) => ({ ...prev, sensors: [...prev.sensors, withId] }))
    return withId
  }, [])

  const updateSensor = useCallback((id: string, patch: Partial<Sensor>) => {
    setData((prev) => ({
      ...prev,
      sensors: prev.sensors.map((s) => (s.id === id ? { ...s, ...patch } : s)),
    }))
  }, [])

  const removeSensor = useCallback((id: string) => {
    setData((prev) => ({ ...prev, sensors: prev.sensors.filter((s) => s.id !== id) }))
  }, [])

  const addLens = useCallback((lens: Omit<Lens, 'id'>) => {
    const withId: Lens = { ...lens, id: makeId('lens') }
    setData((prev) => ({ ...prev, lenses: [...prev.lenses, withId] }))
    return withId
  }, [])

  const updateLens = useCallback((id: string, patch: Partial<Lens>) => {
    setData((prev) => ({
      ...prev,
      lenses: prev.lenses.map((l) => (l.id === id ? { ...l, ...patch } : l)),
    }))
  }, [])

  const removeLens = useCallback((id: string) => {
    setData((prev) => ({ ...prev, lenses: prev.lenses.filter((l) => l.id !== id) }))
  }, [])

  const exportJson = useCallback(() => exportDataAsJson(data), [data])

  const importJson = useCallback((json: string) => {
    const imported = importDataFromJson(json)
    setData(imported)
  }, [])

  return {
    sensors: data.sensors,
    lenses: data.lenses,
    addSensor,
    updateSensor,
    removeSensor,
    addLens,
    updateLens,
    removeLens,
    exportJson,
    importJson,
  }
}

import { SEED_LENSES, SEED_SENSORS } from '../lib/seedData'
import type { Lens, Sensor } from '../lib/types'

const STORAGE_KEY = 'camera-selection-tool/v1'

export interface StoredData {
  schemaVersion: 1
  sensors: Sensor[]
  lenses: Lens[]
}

function isBrowserStorageAvailable(): boolean {
  try {
    const testKey = '__storage_test__'
    window.localStorage.setItem(testKey, '1')
    window.localStorage.removeItem(testKey)
    return true
  } catch {
    return false
  }
}

export function loadData(): StoredData {
  if (!isBrowserStorageAvailable()) {
    return { schemaVersion: 1, sensors: SEED_SENSORS, lenses: SEED_LENSES }
  }

  const raw = window.localStorage.getItem(STORAGE_KEY)
  if (!raw) {
    const seeded: StoredData = { schemaVersion: 1, sensors: SEED_SENSORS, lenses: SEED_LENSES }
    saveData(seeded)
    return seeded
  }

  try {
    const parsed = JSON.parse(raw) as StoredData
    if (parsed.schemaVersion !== 1 || !Array.isArray(parsed.sensors) || !Array.isArray(parsed.lenses)) {
      throw new Error('unrecognized schema')
    }
    return parsed
  } catch {
    // Corrupt/unreadable local data — fall back to the seed set rather than
    // crashing the app. We deliberately don't overwrite the bad data here,
    // in case the user wants to recover it manually from devtools.
    return { schemaVersion: 1, sensors: SEED_SENSORS, lenses: SEED_LENSES }
  }
}

export function saveData(data: StoredData): void {
  if (!isBrowserStorageAvailable()) return
  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
}

export function exportDataAsJson(data: StoredData): string {
  return JSON.stringify(data, null, 2)
}

export function importDataFromJson(json: string): StoredData {
  const parsed = JSON.parse(json) as StoredData
  if (parsed.schemaVersion !== 1 || !Array.isArray(parsed.sensors) || !Array.isArray(parsed.lenses)) {
    throw new Error('This file does not look like a camera-selection-tool export.')
  }
  return parsed
}

import { useState } from 'react'
import type { ExtractKind, ExtractResponse } from '../lib/extraction'
import type { Lens, Sensor } from '../lib/types'
import { BLANK_LENS_DRAFT, BLANK_SENSOR_DRAFT, type LensDraft, type SensorDraft } from './formDrafts'
import { LensForm } from './LensForm'
import { SensorForm } from './SensorForm'

type SuccessResponse = Extract<ExtractResponse, { kind: 'sensor' | 'lens' }>

function fieldsToDraft<D extends object>(
  fields: Record<keyof D, { value: unknown; found: boolean }>,
  blank: D,
): { draft: D; missing: Set<keyof D> } {
  const missing = new Set<keyof D>()
  const draft: Record<string, unknown> = { ...(blank as Record<string, unknown>) }
  for (const key of Object.keys(fields) as (keyof D)[]) {
    const field = fields[key]
    if (!field.found || field.value === null || field.value === undefined) {
      missing.add(key)
    } else {
      draft[key as string] = String(field.value)
    }
  }
  return { draft: draft as D, missing }
}

interface DatasheetImportFormProps {
  kind: ExtractKind
  onSaveSensor?: (sensor: Omit<Sensor, 'id'>) => void
  onSaveLens?: (lens: Omit<Lens, 'id'>) => void
  onCancel: () => void
}

/**
 * Paste a datasheet link -> fetch+extract server-side -> review the
 * pre-filled, editable form -> confirm to save. Nothing is saved without
 * the confirm step (requirements.md §3.1).
 */
export function DatasheetImportForm({ kind, onSaveSensor, onSaveLens, onCancel }: DatasheetImportFormProps) {
  const [url, setUrl] = useState('')
  const [status, setStatus] = useState<'idle' | 'loading' | 'error'>('idle')
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [result, setResult] = useState<SuccessResponse | null>(null)

  async function handleExtract() {
    if (!url.trim()) return
    setStatus('loading')
    setErrorMessage(null)
    setResult(null)
    try {
      const res = await fetch('/api/extract-datasheet', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: url.trim(), kind }),
      })
      const json = (await res.json()) as ExtractResponse
      if (!res.ok || 'error' in json) {
        setErrorMessage('error' in json ? json.error : `Extraction failed (HTTP ${res.status}).`)
        setStatus('error')
        return
      }
      setResult(json)
      setStatus('idle')
    } catch (err) {
      setErrorMessage(err instanceof Error ? err.message : 'Could not reach the extraction service.')
      setStatus('error')
    }
  }

  if (result && result.kind === 'sensor' && onSaveSensor) {
    const { draft, missing } = fieldsToDraft<SensorDraft>(result.fields, BLANK_SENSOR_DRAFT)
    return (
      <div className="flex flex-col gap-3">
        <p className="text-sm text-neutral-600">
          Extracted from <span className="break-all font-mono text-xs">{url}</span>. Review and fix anything flagged
          below, then save.
        </p>
        <SensorForm initial={draft} missingFields={missing} source="datasheet-import" sourceUrl={url} onSave={onSaveSensor} onCancel={onCancel} />
      </div>
    )
  }

  if (result && result.kind === 'lens' && onSaveLens) {
    const { draft, missing } = fieldsToDraft<LensDraft>(result.fields, BLANK_LENS_DRAFT)
    return (
      <div className="flex flex-col gap-3">
        <p className="text-sm text-neutral-600">
          Extracted from <span className="break-all font-mono text-xs">{url}</span>. Review and fix anything flagged
          below, then save.
        </p>
        <LensForm initial={draft} missingFields={missing} source="datasheet-import" sourceUrl={url} onSave={onSaveLens} onCancel={onCancel} />
      </div>
    )
  }

  return (
    <div className="flex flex-col gap-3 rounded border border-neutral-200 p-4">
      <label className="flex flex-col gap-1 text-sm">
        <span>Datasheet link (PDF or vendor spec page)</span>
        <input
          className="rounded border border-neutral-300 p-1.5"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="https://..."
        />
      </label>
      {status === 'error' && <p className="text-sm text-red-700">{errorMessage}</p>}
      <div className="flex gap-2">
        <button
          type="button"
          onClick={handleExtract}
          disabled={status === 'loading' || !url.trim()}
          className="rounded bg-blue-600 px-3 py-1.5 text-sm text-white hover:bg-blue-700 disabled:opacity-50"
        >
          {status === 'loading' ? 'Extracting…' : 'Extract'}
        </button>
        <button type="button" onClick={onCancel} className="rounded border border-neutral-300 px-3 py-1.5 text-sm hover:bg-neutral-100">
          Cancel
        </button>
      </div>
    </div>
  )
}

import { Grid, Html, OrbitControls } from '@react-three/drei'
import { Canvas } from '@react-three/fiber'
import * as THREE from 'three'
import { computeFov, sensorDiagonalMm } from '../lib/optics'
import type { FovRisk } from '../lib/optics'
import type { Lens, Sensor } from '../lib/types'

const RISK_COLOR: Record<FovRisk, string> = {
  normal: '#38bdf8',
  macro: '#fbbf24',
  'extreme-macro': '#fb923c',
  invalid: '#f87171',
}

const RISK_OPACITY: Record<FovRisk, number> = {
  normal: 0.16,
  macro: 0.13,
  'extreme-macro': 0.1,
  invalid: 0.05,
}

interface FovCone3DProps {
  sensor: Sensor
  lens: Lens
  workingDistanceMm: number
}

interface FovStageProps extends FovCone3DProps {
  /** Shared world scale (mm) used for camera position, grid, and clipping so
   * several stages render at an identical 1:1 framing. Defaults to the
   * camera's own working distance when rendered standalone. */
  sceneScaleMm?: number
  /** Fixed height for the canvas; smaller when tiled side by side. */
  heightClass?: string
}

/** Stylized camera body + lens barrel sitting at the frustum apex — reads as "a camera", not just a wireframe box. */
function CameraRig({ sensor }: { sensor: Sensor }) {
  const sw = sensor.widthMm / 2
  const sh = sensor.heightMm / 2
  const lensRadius = Math.max(4, Math.min(sw, sh) * 0.85)

  return (
    <group>
      <mesh position={[0, 0, -20]}>
        <boxGeometry args={[sw * 2.6, sh * 2.6, 24]} />
        <meshStandardMaterial color="#334155" metalness={0.4} roughness={0.5} />
      </mesh>
      <mesh position={[0, 0, -4]} rotation={[Math.PI / 2, 0, 0]}>
        <cylinderGeometry args={[lensRadius, lensRadius * 1.15, 8, 32]} />
        <meshStandardMaterial color="#0f172a" metalness={0.6} roughness={0.3} />
      </mesh>
      {/* Front glass element, a small accent-tinted disc where the frustum apex begins */}
      <mesh position={[0, 0, -0.05]} rotation={[Math.PI / 2, 0, 0]}>
        <circleGeometry args={[lensRadius * 0.85, 32]} />
        <meshStandardMaterial color="#082f49" emissive="#22d3ee" emissiveIntensity={0.35} metalness={0.9} roughness={0.1} />
      </mesh>
    </group>
  )
}

function Frustum({ sensor, lens, workingDistanceMm }: FovCone3DProps) {
  const fov = computeFov(sensor, lens.focalLengthMm, workingDistanceMm)
  const risk = fov.horizontal.risk
  const color = RISK_COLOR[risk]

  const sh = sensor.heightMm / 2

  if (!fov.horizontal.fovMm || !fov.vertical.fovMm) {
    return (
      <group>
        <CameraRig sensor={sensor} />
        <Html position={[0, sh + 20, -15]} center distanceFactor={200}>
          <div className="rounded bg-red-500/90 px-2 py-1 text-xs whitespace-nowrap text-white shadow-lg ring-1 ring-white/20">
            {fov.horizontal.message ?? 'Invalid geometry for this working distance.'}
          </div>
        </Html>
      </group>
    )
  }

  const fw = fov.horizontal.fovMm / 2
  const fh = fov.vertical.fovMm / 2
  const wd = workingDistanceMm

  const corners = [
    new THREE.Vector3(fw, fh, wd),
    new THREE.Vector3(-fw, fh, wd),
    new THREE.Vector3(-fw, -fh, wd),
    new THREE.Vector3(fw, -fh, wd),
  ]

  const footprintEdges = new THREE.BufferGeometry().setFromPoints([...corners, corners[0]])
  const raySets = corners.map((c) => new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), c]))

  return (
    <group>
      <CameraRig sensor={sensor} />

      {/* Frustum rays from the lens to each footprint corner */}
      {raySets.map((geom, i) => (
        <lineSegments key={i}>
          <primitive object={geom} attach="geometry" />
          <lineBasicMaterial color={color} transparent opacity={0.55} />
        </lineSegments>
      ))}

      {/* Footprint outline */}
      <lineSegments>
        <primitive object={footprintEdges} attach="geometry" />
        <lineBasicMaterial color={color} />
      </lineSegments>

      {/* Footprint fill, opacity communicates the uncertainty/risk level */}
      <mesh position={[0, 0, wd]}>
        <planeGeometry args={[fov.horizontal.fovMm, fov.vertical.fovMm]} />
        <meshBasicMaterial color={color} transparent opacity={RISK_OPACITY[risk]} side={THREE.DoubleSide} />
      </mesh>

      <Html position={[0, fh + Math.max(15, fh * 0.08), wd]} center distanceFactor={Math.max(wd, 200)}>
        <div className="rounded bg-slate-900/90 px-2 py-1 text-xs whitespace-nowrap text-slate-100 shadow-lg ring-1 ring-white/10">
          FOV {fov.horizontal.fovMm.toFixed(0)} x {fov.vertical.fovMm.toFixed(0)}mm @ {wd}mm
        </div>
      </Html>
      {risk !== 'normal' && (
        <Html position={[0, -fh - Math.max(15, fh * 0.08), wd]} center distanceFactor={Math.max(wd, 200)}>
          <div
            className="rounded px-2 py-1 text-xs font-medium whitespace-nowrap text-slate-900 shadow-lg"
            style={{ backgroundColor: color }}
          >
            {fov.horizontal.message}
          </div>
        </Html>
      )}
    </group>
  )
}

/**
 * 3D camera-cone "stage": a stylized camera+lens sits at the frustum apex,
 * with the resulting FOV footprint rectangle drawn at the working
 * distance. Color/opacity encode the uncertainty risk level from
 * computeFov rather than hard-blocking sensitive or invalid inputs
 * (requirements.md §3.3). Styled dark to read as an instrument viewport,
 * similar in spirit to commercial lens-selector configurators.
 */
export function FovCone3D({ sensor, lens, workingDistanceMm, sceneScaleMm, heightClass = 'h-[480px]' }: FovStageProps) {
  const wd = Math.max(workingDistanceMm, 1)
  const scale = Math.max(sceneScaleMm ?? wd, 1)
  const diagonal = sensorDiagonalMm(sensor)

  return (
    <div className={`${heightClass} w-full overflow-hidden rounded-xl bg-gradient-to-b from-slate-900 to-slate-950 shadow-inner`}>
      <Canvas camera={{ position: [scale * 0.55, scale * 0.38, scale * 0.85], fov: 50, near: 0.1, far: scale * 10 }}>
        <color attach="background" args={['#0b1220']} />
        <fog attach="fog" args={['#0b1220', scale * 0.8, scale * 6]} />
        <ambientLight intensity={0.55} />
        <directionalLight position={[scale * 0.4, scale * 0.6, scale * 0.2]} intensity={1.1} />
        <pointLight position={[0, 0, 10]} color="#22d3ee" intensity={8} distance={60} />
        <Grid
          args={[scale * 4, scale * 4]}
          position={[0, -diagonal * 4, 0]}
          cellColor="#1e293b"
          sectionColor="#334155"
          fadeDistance={scale * 3}
          fadeStrength={1}
        />
        <Frustum sensor={sensor} lens={lens} workingDistanceMm={wd} />
        <OrbitControls target={[0, 0, scale / 2]} enableDamping dampingFactor={0.08} minDistance={diagonal} maxDistance={scale * 8} />
      </Canvas>
    </div>
  )
}

import 'dotenv/config'
import { createServer } from 'node:http'
import { extractFromUrl } from '../api/_lib/extract.js'
import { isRateLimited } from '../api/_lib/rateLimit.js'

const PORT = Number(process.env.API_PORT ?? 8787)

/**
 * Local stand-in for the Vercel serverless function during `npm run dev`
 * (see vite.config.ts's `server.proxy`). Same handler logic as
 * api/extract-datasheet.ts, just wired to plain node:http instead of the
 * Vercel request/response shape, since there's no `vercel dev` in this
 * environment.
 */
const server = createServer(async (req, res) => {
  if (req.method !== 'POST' || req.url !== '/api/extract-datasheet') {
    res.writeHead(404, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: 'Not found.' }))
    return
  }

  const ip = req.socket.remoteAddress ?? 'unknown'
  if (isRateLimited(ip)) {
    res.writeHead(429, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: 'Too many extraction requests — wait a minute and try again.' }))
    return
  }

  let raw = ''
  for await (const chunk of req) raw += chunk
  const body = raw ? (JSON.parse(raw) as { url?: string; kind?: string }) : {}
  const { url, kind } = body

  if (!url || (kind !== 'sensor' && kind !== 'lens')) {
    res.writeHead(400, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: 'Request must include { url, kind: "sensor" | "lens" }.' }))
    return
  }

  try {
    const result = await extractFromUrl(url, kind)
    res.writeHead('error' in result ? 422 : 200, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify(result))
  } catch (err) {
    res.writeHead(500, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: err instanceof Error ? err.message : 'Extraction failed.' }))
  }
})

server.listen(PORT, () => {
  console.log(`[dev-api] extraction endpoint listening on http://localhost:${PORT}/api/extract-datasheet`)
  if (!process.env.ANTHROPIC_API_KEY) {
    console.warn('[dev-api] ANTHROPIC_API_KEY is not set — extraction will fail at the model-call step. See docs/LEARNINGS.md.')
  }
})

import {
  checkImageCircle,
  checkMountCompatibility,
  computeFov,
  mmPerPixel,
} from './optics'
import type { Lens, Sensor } from './types'

/**
 * Two-camera comparison flow helpers (pure, UI-free).
 *
 * App.tsx renders one panel per CameraSlot. Each panel resolves its
 * sensor/lens (falling back to the first library entry so dropdowns are
 * never empty), derives an *effective* working distance clamped into the
 * slider range for its lens, and shares one world scale across panels so
 * the 3D stages stay a true 1:1 comparison. This module holds that logic
 * so it can be unit-tested without React/three.js.
 */

export const MAX_CAMERAS = 4
export const DEFAULT_WORKING_DISTANCE_MM = 300
export const CAMERAS_STORAGE_KEY = 'camera-selection-tool/cameras-v1'

export interface CameraSlot {
  id: string
  sensorId: string | null
  lensId: string | null
  workingDistanceMm: number
}

export interface ResolvedSlot {
  cam: CameraSlot
  sensor: Sensor | null
  lens: Lens | null
  /** Working distance clamped into this lens's slider range (what the stage shows). */
  effectiveWd: number
}

export interface SliderBounds {
  min: number
  max: number
}

export interface TableRow {
  lensId: string
  lensName: string
  fovHmm: number | null
  fovVmm: number | null
  mmPerPixelH: number | null
  coverage: 'ok' | 'tight' | 'vignetting'
  mountCompatible: boolean
  requiresSpacer: boolean
  risk: string
  valid: boolean
}

let slotCounter = 0

/** Create one comparison slot. IDs are unique within this module session. */
export function createSlot(
  sensorId: string | null,
  lensId: string | null,
  workingDistanceMm: number = DEFAULT_WORKING_DISTANCE_MM,
): CameraSlot {
  slotCounter += 1
  const wd = Number.isFinite(workingDistanceMm) && workingDistanceMm > 0
    ? workingDistanceMm
    : DEFAULT_WORKING_DISTANCE_MM
  return { id: `cam-${Date.now().toString(36)}-${slotCounter}`, sensorId, lensId, workingDistanceMm: wd }
}

/** Slider range for a lens. Mirrors the bounds used by the App panel slider. */
export function getSliderBounds(focalLengthMm: number | null | undefined): SliderBounds {
  if (focalLengthMm === null || focalLengthMm === undefined || !Number.isFinite(focalLengthMm) || focalLengthMm <= 0) {
    return { min: 1, max: 2000 }
  }
  const min = Math.ceil(focalLengthMm) + 1
  const max = Math.max(min + 100, 2000)
  return { min, max }
}

/** Clamp a working distance into a lens's slider range. */
export function clampWorkingDistance(workingDistanceMm: number, focalLengthMm: number | null | undefined): number {
  const { min, max } = getSliderBounds(focalLengthMm)
  if (!Number.isFinite(workingDistanceMm)) return Math.min(Math.max(DEFAULT_WORKING_DISTANCE_MM, min), max)
  return Math.min(Math.max(workingDistanceMm, min), max)
}

/** The WD the stage actually renders for this camera (stored WD clamped to its lens). */
export function effectiveWorkingDistance(cam: CameraSlot, lens: Lens | null): number {
  return clampWorkingDistance(cam.workingDistanceMm, lens?.focalLengthMm ?? null)
}

/** Append a camera seeded from the last slot ("tweak one thing" comparison). No-op at MAX_CAMERAS. */
export function addCameraSlot(slots: CameraSlot[]): CameraSlot[] {
  if (slots.length >= MAX_CAMERAS) return slots
  const last = slots[slots.length - 1]
  const slot = createSlot(last?.sensorId ?? null, last?.lensId ?? null, last?.workingDistanceMm ?? DEFAULT_WORKING_DISTANCE_MM)
  return [...slots, slot]
}

/** Remove one camera. Refuses to drop below a single panel. Unknown ids return the input unchanged. */
export function removeCameraSlot(slots: CameraSlot[], id: string): CameraSlot[] {
  if (slots.length <= 1) return slots
  const next = slots.filter((c) => c.id !== id)
  return next.length === slots.length ? slots : next
}

/**
 * Patch one camera. When the lens changes (or WD is set directly) the stored
 * WD is re-clamped into the resulting lens's valid range so state can never
 * desync from what the slider/stage shows (previously the slider displayed a
 * clamped value while state kept the out-of-range WD, rendering "invalid"
 * FOV under a valid-looking slider position).
 */
export function updateCameraSlot(
  slots: CameraSlot[],
  id: string,
  patch: Partial<CameraSlot>,
  lenses?: Lens[],
): CameraSlot[] {
  return slots.map((c) => {
    if (c.id !== id) return c
    const merged: CameraSlot = { ...c, ...patch, id: c.id }
    if (lenses && (patch.lensId !== undefined || patch.workingDistanceMm !== undefined)) {
      const lens = lenses.find((l) => l.id === merged.lensId) ?? null
      merged.workingDistanceMm = clampWorkingDistance(merged.workingDistanceMm, lens?.focalLengthMm ?? null)
    }
    return merged
  })
}

/** Resolve each slot to its sensor/lens with first-available fallback + clamped WD. */
export function resolveSlots(cameras: CameraSlot[], sensors: Sensor[], lenses: Lens[]): ResolvedSlot[] {
  return cameras.map((cam) => {
    const sensor = sensors.find((s) => s.id === cam.sensorId) ?? sensors[0] ?? null
    const lens = lenses.find((l) => l.id === cam.lensId) ?? lenses[0] ?? null
    return { cam, sensor, lens, effectiveWd: effectiveWorkingDistance(cam, lens) }
  })
}

/** Shared world scale: max effective WD across resolvable panels, else the default. */
export function sharedScaleMm(resolved: ResolvedSlot[]): number {
  const distances = resolved.filter((r) => r.sensor && r.lens).map((r) => r.effectiveWd)
  return distances.length > 0 ? Math.max(...distances) : DEFAULT_WORKING_DISTANCE_MM
}

/** De-duplicated sensors across panels (feeds the to-scale overlay). */
export function sensorsInPlay(resolved: ResolvedSlot[]): Sensor[] {
  const seen = new Map<string, Sensor>()
  for (const r of resolved) if (r.sensor) seen.set(r.sensor.id, r.sensor)
  return [...seen.values()]
}

/** De-duplicated lenses across panels (feeds the comparison table). */
export function lensesInPlay(resolved: ResolvedSlot[]): Lens[] {
  const seen = new Map<string, Lens>()
  for (const r of resolved) if (r.lens) seen.set(r.lens.id, r.lens)
  return [...seen.values()]
}

/** Panel grid/height classes for 1 vs tiled layouts. */
export function panelLayout(count: number): { gridColsClass: string; panelHeight: string } {
  if (count <= 1) return { gridColsClass: 'grid-cols-1', panelHeight: 'h-[480px]' }
  return { gridColsClass: 'grid-cols-1 md:grid-cols-2', panelHeight: 'h-[340px]' }
}

/** One comparison-table row: first camera's sensor vs one lens at camera-1's effective WD. */
export function buildTableRow(sensor: Sensor, lens: Lens, workingDistanceMm: number): TableRow {
  const fov = computeFov(sensor, lens.focalLengthMm, workingDistanceMm)
  const circle = checkImageCircle(lens, sensor)
  const mount = checkMountCompatibility(lens.mount, sensor.mount)
  const valid = fov.horizontal.fovMm !== null && fov.vertical.fovMm !== null
  return {
    lensId: lens.id,
    lensName: lens.name,
    fovHmm: fov.horizontal.fovMm,
    fovVmm: fov.vertical.fovMm,
    mmPerPixelH: fov.horizontal.fovMm !== null ? mmPerPixel(fov.horizontal.fovMm, sensor.resolutionH) : null,
    coverage: circle.status,
    mountCompatible: mount.compatible,
    requiresSpacer: mount.requiresSpacer,
    risk: fov.horizontal.risk,
    valid,
  }
}

/** Overlay label rendered on each 3D stage (mirrors FovCone3D's Html badge). */
export function overlayLabel(sensor: Sensor, lens: Lens, workingDistanceMm: number): string {
  const fov = computeFov(sensor, lens.focalLengthMm, workingDistanceMm)
  if (fov.horizontal.fovMm === null || fov.vertical.fovMm === null) {
    return fov.horizontal.message ?? 'Invalid geometry for this working distance.'
  }
  return `FOV ${fov.horizontal.fovMm.toFixed(0)} x ${fov.vertical.fovMm.toFixed(0)}mm @ ${workingDistanceMm}mm`
}

export interface TwoCameraView {
  resolved: ResolvedSlot[]
  sharedScale: number
  playSensors: Sensor[]
  playLenses: Sensor[] | Lens[]
  tableRows: TableRow[]
  overlays: string[]
  tableWd: number
}

/**
 * Full derived view for the comparison flow: per-panel resolution, shared
 * scale, overlay labels, and the comparison table. A WD change on any panel
 * flows into its FOV readout (via resolved[].effectiveWd), its overlay
 * label, the shared scale, and — for camera 1 — the table rows, which is
 * what the integration test pins down.
 */
export function computeTwoCameraView(sensors: Sensor[], lenses: Lens[], cameras: CameraSlot[]): TwoCameraView {
  const resolved = resolveSlots(cameras, sensors, lenses)
  const sharedScale = sharedScaleMm(resolved)
  const playSensors = sensorsInPlay(resolved)
  const playLenses = lensesInPlay(resolved)
  const first = resolved[0]
  const tableWd = first ? first.effectiveWd : DEFAULT_WORKING_DISTANCE_MM
  const tableRows = first?.sensor ? playLenses.map((l) => buildTableRow(first.sensor as Sensor, l, tableWd)) : []
  const overlays = resolved.map((r) =>
    r.sensor && r.lens ? overlayLabel(r.sensor, r.lens, r.effectiveWd) : 'Add a sensor and a lens to view this camera.',
  )
  return { resolved, sharedScale, playSensors, playLenses, tableRows, overlays, tableWd }
}

// --- Camera-slot persistence (separate key so the sensor/lens schema is untouched) ---

function storageAvailable(): boolean {
  try {
    if (typeof window === 'undefined' || !window.localStorage) return false
    const k = '__storage_test__'
    window.localStorage.setItem(k, '1')
    window.localStorage.removeItem(k)
    return true
  } catch {
    return false
  }
}

function sanitizeSlot(raw: unknown): CameraSlot | null {
  if (typeof raw !== 'object' || raw === null) return null
  const r = raw as Record<string, unknown>
  if (typeof r['id'] !== 'string' || r['id'].length === 0) return null
  const sensorId = r['sensorId']
  const lensId = r['lensId']
  const wd = r['workingDistanceMm']
  return {
    id: r['id'] as string,
    sensorId: typeof sensorId === 'string' ? sensorId : null,
    lensId: typeof lensId === 'string' ? lensId : null,
    workingDistanceMm: typeof wd === 'number' && Number.isFinite(wd) && wd > 0 ? wd : DEFAULT_WORKING_DISTANCE_MM,
  }
}

/** Validate + sanitize a raw persisted value. Returns null when nothing usable was stored. */
export function parseCameraSlots(raw: unknown): CameraSlot[] | null {
  if (!Array.isArray(raw)) return null
  const slots = raw.map(sanitizeSlot).filter((s): s is CameraSlot => s !== null)
  if (slots.length === 0 || slots.length > MAX_CAMERAS) return null
  return slots
}

/** Load persisted camera slots, or null when absent/corrupt (caller falls back to a single slot). */
export function loadCameraSlots(): CameraSlot[] | null {
  if (!storageAvailable()) return null
  try {
    const raw = window.localStorage.getItem(CAMERAS_STORAGE_KEY)
    if (!raw) return null
    return parseCameraSlots(JSON.parse(raw))
  } catch {
    return null
  }
}

/** Persist camera slots; silently no-ops outside a browser. */
export function saveCameraSlots(slots: CameraSlot[]): void {
  if (!storageAvailable()) return
  try {
    window.localStorage.setItem(CAMERAS_STORAGE_KEY, JSON.stringify(slots))
  } catch {
    // Quota/private-mode failures must never break the comparison UI.
  }
}
